<?php defined('BASEPATH') OR exit('No direct script access allowed'); ?><link rel="stylesheet" href="<?= base_url('theme/dist/css/pharmacy_directory.css?v='.filemtime(FCPATH.'theme/dist/css/pharmacy_directory.css')); ?>">
<div class="pharma-workspace">
  <header class="pharma-hero"><div><span class="pharma-kicker"><span class="pharma-pulse"></span> Pharmacy workspace</span><h1>More tools</h1><p>One calm directory for the pharmacy website, fulfilment locations, patient care and reports.</p></div><div class="pharma-hero-actions"><a class="pharma-btn pharma-btn-light" href="<?= base_url('dashboard'); ?>"><i class="fa fa-arrow-left"></i> Overview</a><a class="pharma-btn pharma-btn-primary" href="<?= base_url('pharmacy_workspace/locations'); ?>"><i class="fa fa-map-marker"></i> Locations</a></div></header>
  <div class="pharma-tool-search"><i class="fa fa-search" aria-hidden="true"></i><label class="sr-only" for="pharmacy-tool-search">Find a tool</label><input type="search" id="pharmacy-tool-search" placeholder="Search patients, website, locations, reports…" autocomplete="off"></div>
  <div class="pharma-tool-grid" data-pharmacy-tools>
    <?php foreach ($tool_groups as $name => $tools): ?><section class="pharma-tool-card" data-tool-group><div class="pharma-eyebrow"><?= htmlspecialchars($name); ?></div><div class="pharma-tool-list"><?php foreach ($tools as $tool): ?><a data-tool data-search="<?= htmlspecialchars($name.' '.$tool['label'].' '.$tool['description'], ENT_QUOTES, 'UTF-8'); ?>" href="<?= htmlspecialchars($tool['url'], ENT_QUOTES, 'UTF-8'); ?>"><span><strong><?= htmlspecialchars($tool['label']); ?></strong><small><?= htmlspecialchars($tool['description']); ?></small></span><i class="fa fa-angle-right"></i></a><?php endforeach; ?></div></section><?php endforeach; ?>
  </div><p class="pharma-empty" id="pharmacy-tools-empty" role="status" hidden>No matching tools are available to your role.</p>
</div>
<script>(function(){var q=document.getElementById('pharmacy-tool-search');if(!q)return;q.addEventListener('input',function(){var term=q.value.toLowerCase().trim(),shown=0;document.querySelectorAll('[data-tool-group]').forEach(function(group){var count=0;group.querySelectorAll('[data-tool]').forEach(function(item){var ok=!term||item.getAttribute('data-search').toLowerCase().indexOf(term)!==-1;item.hidden=!ok;if(ok){count++;shown++;}});group.hidden=count===0;});document.getElementById('pharmacy-tools-empty').hidden=shown!==0;});})();</script>
